    FE(["Mijn","buddy","helpen","me."], 2, "helpt", "Singular: helpt.", ["v-buddy"]),
    FB("Op maandag is er een ___ langs alle afdelingen.", ["kennismakingsronde"], "Ronda.", ["v-kennismakingsronde"], choices=["kennismakingsronde","buddy","training"], tr="Na segunda há uma ronda de apresentações por todos os departamentos."),
    LI("Als je vragen hebt, kun je altijd bij mij terecht.", ["Als je vragen hebt, kun je altijd bij mij terecht","Als je vragen hebt kun je altijd bij mij terecht"], "Se tiveres perguntas, podes sempre vir ter comigo.", "terechtkunnen bij.", ["v-buddy"]),
    WO("Bem-vindo, novo colega!", ["Welkom,","nieuwe","collega!"], "Saudação.", ["v-nieuwe-collega"]),
