    FB("Een goede leidinggevende durft te ___.", ["delegeren"], "Delegar.", ["v-delegeren"], choices=["delegeren","verdelen","nemen"], tr="Um bom chefe tem coragem de delegar."),
    LI("Dat pak ik zelf wel op.", ["Dat pak ik zelf wel op"], "Disso trato eu.", "oppakken.", ["v-oppakken"]),
    WO("Isso é da tua responsabilidade.", ["Dat","is","jouw","verantwoordelijkheid"], "Ordem.", ["v-verantwoordelijkheid"]),
