L(18, "Diversidade no trabalho", "Een inclusieve werkvloer.",
  ["Falar de diversidade e inclusão no local de trabalho"],
  vocab=[V("v-diversiteit","diversiteit","diversidade","noun","de"), V("v-werkvloer","werkvloer","local de trabalho (chão da fábrica)","noun","de"),
         V("v-gelijke-kansen","gelijke kansen","igualdade de oportunidades","expression"), V("v-achtergrond-cultuur","culturele achtergrond","origem cultural","expression")],
  ex=[("Diversiteit maakt een team sterker.","A diversidade torna uma equipa mais forte."),("Op de werkvloer werken mensen uit twaalf landen.","No local de trabalho trabalham pessoas de doze países."),("Iedereen verdient gelijke kansen.","Toda a gente merece igualdade de oportunidades."),("We hebben verschillende culturele achtergronden.","Temos origens culturais diferentes.")],
  review=["v-inclusief","v-multicultureel"],
  cefr=C, exs=[
    MA([("diversiteit","diversidade"),("werkvloer","local de trabalho"),("gelijke kansen","igualdade de oportunidades"),("culturele achtergrond","origem cultural")], "Diversidade.", ["v-diversiteit","v-werkvloer","v-gelijke-kansen","v-achtergrond-cultuur"]),
    CO("text","Een divers team", "In ons magazijn werken mensen uit twaalf landen, van Portugal tot Syrië. Die diversiteit is een kracht: we leren veel van elkaar. Toch zijn er ook uitdagingen, zoals misverstanden door taal of cultuur. Daarom hebben we duidelijke afspraken, werken we met eenvoudige taal en vieren we samen verschillende feestdagen. Iedereen moet gelijke kansen krijgen, ongeacht zijn achtergrond.",
       [("De quantos países são os trabalhadores?", ["*Doze","Dois","Vinte"]),("Que desafio referem?", ["*Mal-entendidos por língua ou cultura","Salários baixos","Turnos longos"]),("O que fazem?", ["*Acordos claros, linguagem simples, festejam várias datas","Proíbem outras línguas","Nada"])],
       "Inclusão.", ["v-diversiteit","v-gelijke-kansen"]),
    TR("pt-nl","A diversidade torna uma equipa mais forte.", ["Diversiteit maakt een team sterker"], "maken + comparativo.", ["v-diversiteit"]),
    TR("pt-nl","Toda a gente merece igualdade de oportunidades.", ["Iedereen verdient gelijke kansen"], "verdienen.", ["v-gelijke-kansen"]),
    FE(["Iedereen","verdienen","gelijke","kansen."], 1, "verdient", "Iedereen + singular.", ["v-gelijke-kansen"]),
    FB("Op de ___ spreken we Nederlands en Engels.", ["werkvloer"], "Local de trabalho.", ["v-werkvloer"], choices=["werkvloer","diversiteit","achtergrond"], tr="No local de trabalho falamos neerlandês e inglês."),
    AR("werkvloer","o local de trabalho","de", "De vloer.", ["v-werkvloer"]),
    LI("Ongeacht je achtergrond krijg je hier dezelfde kansen.", ["Ongeacht je achtergrond krijg je hier dezelfde kansen"], "Independentemente da tua origem, aqui tens as mesmas oportunidades.", "ongeacht = independentemente de.", ["v-achtergrond-cultuur"]),
    WO("Temos origens diferentes.", ["We","hebben","verschillende","achtergronden"], "Ordem.", ["v-achtergrond-cultuur"]),
    MC("«Ongeacht» significa…", ["*independentemente de","por causa de|Não.","apesar de|Seria ondanks."], "Vocabulário.", ["v-gelijke-kansen"]),
  ], diff=4, mins=7)

