    TR("pt-nl","O diretor faz um discurso.", ["De directeur houdt een toespraak"], "een toespraak houden.", ["v-toespraak"]),
    FE(["De","directeur","maakt","een","toespraak."], 2, "houdt", "Colocação: een toespraak houden.", ["v-toespraak"]),
    FB("Namens iedereen: bedankt voor je ___!", ["inzet"], "Empenho.", ["v-inzet"], choices=["inzet","afscheid","toespraak"], tr="Em nome de todos: obrigado pelo teu empenho!"),
    LI("Namens het hele team wens ik je veel geluk.", ["Namens het hele team wens ik je veel geluk"], "Em nome de toda a equipa desejo-te muitas felicidades.", "namens.", ["v-afscheid"]),
    WO("Vamos ter saudades tuas.", ["We","gaan","je","missen"], "Ordem.", ["v-we-gaan-je-missen"]),
    SW("Escreva um pequeno discurso de despedida (5–6 frases) para um colega que muda de emprego.", ["Beste Lisa,\nVandaag nemen we afscheid van jou. Je hebt vier jaar in ons team gewerkt en je was altijd behulpzaam en vrolijk. We gaan vooral je lekkere taarten op vrijdag missen! Namens iedereen: bedankt voor je inzet. Veel succes in je nieuwe baan in Utrecht. Proost op Lisa!"], ["Abertura", "Algo pessoal e concreto", "Agradecimento", "Desejo para o futuro"], 50, "Discurso.", ["v-toespraak","v-afscheid"]),
