    WO("Vou coordenar com a minha colega.", ["Ik","stem","het","af","met","mijn","collega"], "Separável.", ["v-afstemmen-met"]),
    MC("Porque é útil coordenar?", ["*Para evitar trabalho duplicado e erros","Para trabalhar mais|Não.","Para não falar com ninguém|Não."], "Objetivo.", ["v-dubbel-werk"]),
